// Generated lookup data for Android phone models.
// dataset is generated by scripts/generate-phone-models.mjs from Google's Play
// supported-device catalog — DO NOT edit the JSON by hand; re-run `npm run phones:generate`.
// Lookup is exact (case-sensitive) on the model code that Android reports; no fuzzy matching.
import raw from "@/data/generated/androidPhoneModels.json";

export interface AndroidPhoneEntry {
  retailBrand: string;
  marketingName: string;
  deviceCode: string;
  modelCode: string;
}

export interface AndroidPhoneStats {
  totalEntries: number;
  phoneEntries: number;
  excludedEntries: number;
  duplicateRows: number;
  ambiguousRows: number;
  ambiguousModelCodes: number;
  excludedBreakdown: {
    malformedRow: number;
    emptyModelCode: number;
    noDisplayName: number;
    chromebook: number;
    tv: number;
    wearable: number;
    automotive: number;
    router: number;
    audioOrSmartDisplay: number;
    tablet: number;
  };
}

export interface AndroidPhoneDataset {
  schemaVersion: number;
  sourceUrl: string;
  generatedAt: string;
  stats: AndroidPhoneStats;
  phones: AndroidPhoneEntry[];
  ambiguous: Array<{
    modelCode: string;
    variants: Array<{
      retailBrand: string;
      marketingName: string;
      deviceCode: string;
    }>;
  }>;
}

const dataset = raw as unknown as AndroidPhoneDataset;

// Model codes from the catalog that resolve to several regional/marketing variants;
// lookup deliberately returns null for these instead of guessing.
const ambiguousCodes = new Set<string>(dataset.ambiguous.map((entry) => entry.modelCode));

// Index: exact modelCode -> entry (first occurrence wins; catalog casing preserved).
const byModelCode = new Map<string, AndroidPhoneEntry>();
for (const entry of dataset.phones) {
  if (byModelCode.has(entry.modelCode)) continue;
  byModelCode.set(entry.modelCode, entry);
}

/** Trim + strip surrounding quotes; casing is preserved for lookup. */
export function normalizeModelCode(raw: string): string {
  return raw.trim().replace(/^["']+|["']+$/g, "").trim();
}

/** Exact, case-sensitive model-code lookup. null when unmapped or ambiguous. */
export function lookupAndroidPhone(modelCode: string): AndroidPhoneEntry | null {
  const key = normalizeModelCode(modelCode);
  if (!key || ambiguousCodes.has(key)) return null;
  return byModelCode.get(key) ?? null;
}

/** Number of distinct model codes that can resolve to a phone marketing name. */
export function getAndroidPhoneCount(): number {
  return byModelCode.size;
}

export function getAndroidPhoneStats(): AndroidPhoneStats {
  return dataset.stats;
}
